+#include "oops/compressedOops.hpp"
@@ -1073,0 +1076,10 @@
+bool compressed_oop_constants_fit_in_31_bits() {
+  const uintptr_t heap_range = (uintptr_t)CompressedOops::end() -
+                               (uintptr_t)CompressedOops::base();
+  if (heap_range == 0) {
+    return true;
+  }
+  const jlong max_encoded_oop = (jlong)((heap_range - 1) >> CompressedOops::shift());
+  return Assembler::is_uimm(max_encoded_oop, 31);
+}
